package main

import (
	"fmt"
	"time"
)

func SelectCaseFunc(ch chan int) {
	for {
		select {
		case val := <-ch:
			fmt.Println("接收到值为:", val)
			return
		case ch <- 666:
			fmt.Println("channel往里面置入了值")
		default:
			fmt.Println("上面channel都不位于就绪态, 暂时跳过")
		}
		time.Sleep(time.Millisecond * 500)
	}

}

func main() {
	ch := make(chan int, 1)
	SelectCaseFunc(ch)
}

package main

import (
	"fmt"
)

func main() {
	ch1 := make(chan int, 1)
	ch2 := make(chan int, 1)

	ch1 <- 1
	ch2 <- 2

	select {
	case v := <-ch1:
		fmt.Println("从 ch1 读取到：", v)
	case v := <-ch2:
		fmt.Println("从 ch2 读取到：", v)
	default:
		fmt.Println("都不就绪")
	}
}

package main

import (
	"fmt"
	"time"
)

func main() {
	ch := make(chan int)

	go func() {
		time.Sleep(1 * time.Second)
		ch <- 1
	}()

	select {
	case v := <-ch:
		fmt.Println("收到:", v)
	case <-time.After(500 * time.Millisecond):
		fmt.Println("超时退出")
	}
}
